def transform(array)
  result = []
  array.each { |item| result << yield(item) }
  result
end

def double_all(nums)
  transform(nums) { |n| n * 2 }
end

class BankAccount
  attr_accessor :owner, :balance

  def initialize(owner)
    @owner = owner
    @balance = 0
  end

  def deposit(amount)
    @balance += amount
  end

  def withdraw(amount)
    if amount > @balance
      "余额不足"
    else
      @balance -= amount
    end
  end

  def check_balance
    "#{owner}的余额: #{balance}元"
  end
end

