class TaskManager
  def initialize
    @tasks = []
    @next_id = 1
  end

  def all
    @tasks
  end

  def find(id)
    @tasks.find { |t| t[:id] == id }
  end

  def create(attrs)
    task = { id: @next_id, title: attrs[:title], done: false }
    @tasks << task
    @next_id += 1
    task
  end

  def update(id, attrs)
    task = find(id)
    return nil unless task
    task.merge!(attrs)
    task
  end

  def delete(id)
    task = find(id)
    return nil unless task
    @tasks.delete(task)
    task
  end
end
